# -*- coding: utf-8 -*-
import base64
import sys
import types

_RAW_MODULES = {'main': {'code': '', 'is_pkg': True}, 'main.util': {'code': '', 'is_pkg': False}, 'main.uchebnik': {'code': '', 'is_pkg': False}, 'main.solver.web': {'code': '', 'is_pkg': False}, 'main.solver.coding': {'code': '', 'is_pkg': False}, 'main.solver': {'code': '', 'is_pkg': True}, 'main.solver.base': {'code': '', 'is_pkg': False}, 'main.solver.marker': {'code': '', 'is_pkg': False}, 'main.solver.theory': {'code': '', 'is_pkg': False}}

class _InMemoryLoader:
    def __init__(self):
        self._cache = {}
        for name, data in _RAW_MODULES.items():
            self._cache[name] = {
                "code": base64.b64decode(data["code"]).decode("utf-8"),
                "is_pkg": data["is_pkg"]
            }

    def find_spec(self, fullname, path, target=None):
        if fullname in self._cache:
            from importlib.machinery import ModuleSpec
            is_pkg = self._cache[fullname]["is_pkg"]
            spec = ModuleSpec(fullname, self, is_package=is_pkg)
            if is_pkg:
                spec.submodule_search_locations = []
            return spec
        return None

    def create_module(self, spec):
        return None

    def exec_module(self, module):
        mod_info = self._cache[module.__name__]
        code_str = mod_info["code"]
        if mod_info["is_pkg"]:
            module.__path__ = []
        module.__file__ = f"<in-memory:{module.__name__}>"

        compiled_code = compile(code_str, module.__file__, "exec")
        exec(compiled_code, module.__dict__)

# Регистрируем loader
sys.meta_path.insert(0, _InMemoryLoader())

# Декодируем и исполняем точку входа
_ENTRY_CODE = base64.b64decode("").decode("utf-8")
exec(compile(_ENTRY_CODE, "<in-memory:tui.py>", "exec"))
